package net.civeira.phylax.feature.observe.observedsource.domain.valueholder;

import java.util.Optional;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;
import org.mockito.Mockito;

import net.civeira.phylax.common.value.validation.ConstraintFailList;
import net.civeira.phylax.feature.observe.observedsource.domain.ObservedSource;
import net.civeira.phylax.feature.observe.observedsource.domain.valueobject.ScrubFieldsVO;

class ScrubFieldsValueHolderUnitTest {

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign plain values on the holder of scrub fields of observed source")
  void test_scrub_fields_value_holder_assign_plain_value() {
    Object holder = new Object();
    ScrubFieldsValueHolder<Object> value = new ScrubFieldsValueHolder<>(holder);
    Assertions.assertSame(holder, value.scrubFields("one"), "Setters must return the holder");
    Assertions.assertTrue(value.getScrubFieldsValue().isPresent(),
        "The plain value must be stored");
    Assertions.assertEquals("one", value.getScrubFields().orElse(null),
        "The plain value must be recovered");
    Assertions.assertSame(holder, value.scrubFieldsNull(), "Setters must return the holder");
    Assertions.assertTrue(value.getScrubFieldsValue().isPresent(),
        "A null value object must be stored");
    Assertions.assertFalse(value.getScrubFields().isPresent(),
        "A null value must not have content");
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign value objects on the holder of scrub fields of observed source")
  void test_scrub_fields_value_holder_assign_value_object() {
    Object holder = new Object();
    ScrubFieldsValueHolder<Object> value = new ScrubFieldsValueHolder<>(holder);
    ScrubFieldsVO vo = ScrubFieldsVO.from("one");
    Assertions.assertFalse(value.getScrubFieldsValue().isPresent(), "A new holder must be empty");
    Assertions.assertSame(holder, value.scrubFields(vo), "Setters must return the holder");
    Assertions.assertSame(vo, value.getScrubFieldsValue().orElseThrow());
    Assertions.assertSame(holder, value.scrubFields(Optional.empty()));
    Assertions.assertFalse(value.getScrubFieldsValue().isPresent(),
        "An empty optional must clear the value");
    Assertions.assertSame(holder, value.scrubFields(Optional.of(vo)));
    Assertions.assertSame(vo, value.getScrubFieldsValue().orElseThrow());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test read the value of the holder of scrub fields of observed source against the original")
  void test_scrub_fields_value_holder_read() {
    Object holder = new Object();
    ScrubFieldsValueHolder<Object> value = new ScrubFieldsValueHolder<>(holder);
    ScrubFieldsVO vo = ScrubFieldsVO.from("one");
    ScrubFieldsVO other = ScrubFieldsVO.from("one");
    ObservedSource original = Mockito.mock(ObservedSource.class);
    Mockito.when(original.getScrubFieldsValue()).thenReturn(other);
    ConstraintFailList fails = new ConstraintFailList();
    Assertions.assertSame(other, value.readScrubFields(Optional.of(original), fails),
        "Without value, the original must be used");
    Assertions.assertTrue(fails.isEmpty());
    Assertions.assertNotNull(value.readScrubFields(Optional.empty(), fails),
        "Without value and original a null value is returned");
    Assertions.assertTrue(fails.isEmpty(), "An optional value is never reported as missing");
    value.scrubFields(vo);
    ConstraintFailList others = new ConstraintFailList();
    Assertions.assertSame(vo, value.readScrubFields(Optional.of(original), others),
        "With value, the original is ignored");
    Assertions.assertSame(vo, value.readScrubFields(Optional.empty(), others));
    Assertions.assertTrue(others.isEmpty());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test unset the value of the holder of scrub fields of observed source")
  void test_scrub_fields_value_holder_unset() {
    Object holder = new Object();
    ScrubFieldsValueHolder<Object> value = new ScrubFieldsValueHolder<>(holder);
    ScrubFieldsVO vo = ScrubFieldsVO.from("one");
    value.scrubFields(vo);
    Assertions.assertSame(holder, value.unsetScrubFieldsIfMatches("scrubFields_other"));
    Assertions.assertTrue(value.getScrubFieldsValue().isPresent(),
        "Other field name must keep the value");
    Assertions.assertSame(holder, value.unsetScrubFieldsIfMatches("scrubFields"));
    Assertions.assertFalse(value.getScrubFieldsValue().isPresent(),
        "The field name must clear the value");
    value.scrubFields(vo);
    Assertions.assertSame(holder, value.unsetScrubFields());
    Assertions.assertFalse(value.getScrubFieldsValue().isPresent(), "Unset must clear the value");
  }
}
